# Build prefix set
prefixes = set()
for w in words:
    for i in range(1, len(w)+1):
        prefixes.add(w[:i])
print("Prefixes built:", len(prefixes))

board = [
    ['a','b','r','l'],
    ['e','i','t','e'],
    ['i','o','n','s'],
    ['f','p','e','i']
]

# Precompute neighbors
neighbors = {}
for r in range(4):
    for c in range(4):
        nbrs = []
        for dr in (-1,0,1):
            for dc in (-1,0,1):
                if dr==0 and dc==0: continue
                nr, nc = r+dr, c+dc
                if 0<=nr<4 and 0<=nc<4:
                    nbrs.append((nr,nc))
        neighbors[(r,c)] = nbrs

max_len = 0
best_words = set()

# Use iterative DFS to avoid recursion limit? recursion depth max 16, fine.
def dfs(r, c, visited_mask, path):
    global max_len, best_words
    # visited_mask bit index = r*4 + c
    bit = 1 << (r*4 + c)
    # current path already validated as prefix by caller
    if path in words:
        L = len(path)
        if L > max_len:
            max_len = L
            best_words = {path}
        elif L == max_len:
            best_words.add(path)
